// Step 1 of the exercise: replace these with questions people ask you every week.
const questions = [
  'How do I reset my password?',
  'The VPN will not connect, what do I do?',
  'Where do I submit an expense receipt?',
  'How do I book a meeting room?',
];
return questions.map(question => ({ json: { question } }));

// Step 2 of the exercise: add your own FAQ entry here, then run the workflow again.
// Each entry has keywords to match, an answer and where the answer comes from.
const faq = [
  { keywords: ['password', 'reset'], answer: 'Go to the self-service password page and choose "Forgot password". You will get a code on your registered phone.', source: 'IT Help Desk Guide' },
  { keywords: ['vpn'], answer: 'Install the VPN client from the software centre and sign in with your work account and multi-factor authentication.', source: 'IT Help Desk Guide' },
  { keywords: ['ticket', 'help desk'], answer: 'Open a ticket in the IT portal or email the help desk. Report urgent outages by phone.', source: 'IT Help Desk Guide' },
  { keywords: ['expense', 'receipt'], answer: 'Submit expense claims in the finance portal within 30 days of the expense. Attach a receipt for every item.', source: 'Expense Policy' },
  { keywords: ['laptop', 'equipment'], answer: 'On day one you receive your laptop, badge and accounts.', source: 'Onboarding Guide' },
];

return $input.all().map(item => {
  const q = item.json.question.toLowerCase();
  const hit = faq.find(f => f.keywords.some(k => q.includes(k)));
  return { json: { question: item.json.question, answer: hit ? hit.answer : null, source: hit ? hit.source : null } };
});

// Builds one message: each question with its answer and source, and a list of gaps to fix.
const rows = $input.all().map(i => i.json);
const answered = rows.filter(r => r.answer).length;
const text = rows.map((r, n) => `${n + 1}. ${r.question}\n   ${r.answer ? `${r.answer}\n   Source: ${r.source}` : 'No answer yet: add it to the FAQ.'}`).join('\n\n');
return [{ json: { answered, total: rows.length, gaps: rows.filter(r => !r.answer).map(r => r.question), digest: text } }];
